import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
import { rankBetween, orderedIssues } from '../src/modules/work/boards.js';
let server, owner, guest, org, project, issues, label, guestId;
beforeEach(async () => {
  server = await testServer(); owner = server.agent(); guest = server.agent();
  await owner('POST', '/auth/signup', { name: 'Owner', email: 'owner@board.test', password: 'correct-horse-123' });
  guestId = (await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@board.test', password: 'correct-horse-123' })).data.user.id;
  org = (await owner('POST', '/orgs', { name: 'Board Org' })).data.organization;
  await owner('POST', '/orgs/' + org.id + '/members', { userId: guestId, role: 'guest' });
  project = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'BR', name: 'Board' })).data.project;
  issues = [];
  for (const title of ['First', 'Second', 'Third']) issues.push((await owner('POST', '/projects/' + project.id + '/issues', { title })).data.issue);
  label = (await owner('POST', '/projects/' + project.id + '/labels', { name: 'Release' })).data.label;
});
afterEach(async () => { await server.close(); });
async function board() { return (await owner('GET', '/projects/' + project.id + '/board')).data; }
test('board columns follow workflow and new issue order is stable', async () => {
  const result = await board();
  assert.deepEqual(result.columns.map(column => column.status.id), project.statuses.map(status => status.id));
  assert.deepEqual(result.columns[0].issues.map(issue => issue.id), issues.map(issue => issue.id));
});
test('moving within a column persists exact anchor order', async () => {
  const result = await owner('POST', '/issues/' + issues[2].id + '/move', { statusId: project.statuses[0].id, beforeId: issues[0].id });
  assert.equal(result.status, 200); assert(result.data.issue.rank < issues[0].rank);
  assert.deepEqual((await board()).columns[0].issues.map(issue => issue.id), [issues[2].id, issues[0].id, issues[1].id]);
});
test('moving across columns updates status and appends after existing work', async () => {
  const target = project.statuses[1].id;
  await owner('POST', '/issues/' + issues[0].id + '/move', { statusId: target });
  await owner('POST', '/issues/' + issues[1].id + '/move', { statusId: target, afterId: issues[0].id });
  assert.deepEqual((await board()).columns[1].issues.map(issue => issue.id), [issues[0].id, issues[1].id]);
  assert.equal((await owner('GET', '/issues/' + issues[1].id)).data.issue.statusId, target);
});
test('invalid move anchor leaves the issue and column untouched', async () => {
  assert.equal((await owner('POST', '/issues/' + issues[0].id + '/move', { statusId: project.statuses[1].id, beforeId: issues[1].id })).status, 422);
  assert.equal((await owner('GET', '/issues/' + issues[0].id)).data.issue.statusId, project.statuses[0].id);
});
test('rank exhaustion rebalances destination atomically and preserves order', async () => {
  server.ctx.db.prepare('UPDATE issues SET rank=1 WHERE project_id=?').run(project.id);
  assert.equal((await owner('POST', '/issues/' + issues[2].id + '/move', { statusId: project.statuses[0].id, afterId: issues[0].id })).status, 200);
  const ranked = (await board()).columns[0].issues;
  const expected = orderedIssues(issues.slice(0, 2).map(issue => ({ ...issue, rank: 1 })));
  const expectedIds = expected.map(issue => issue.id);
  expectedIds.splice(expectedIds.indexOf(issues[0].id) + 1, 0, issues[2].id);
  assert.deepEqual(ranked.map(issue => issue.id), expectedIds);
  assert.equal(new Set(ranked.map(issue => issue.rank)).size, 3);
});
test('bulk status assignee and label replacement persists all issues', async () => {
  const userId = (await owner('GET', '/me')).data.user.id;
  const result = await owner('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: issues.map(issue => issue.id), changes: { statusId: project.statuses[1].id, assigneeId: userId, labelIds: [label.id] } });
  assert.equal(result.status, 200, JSON.stringify(result.data)); assert.equal(result.data.count, 3);
  for (const issue of result.data.items) { assert.equal(issue.statusId, project.statuses[1].id); assert.equal(issue.assigneeId, userId); assert.equal(issue.labels[0].id, label.id); }
});
test('bulk invalid label is rejected before any mutation', async () => {
  assert.equal((await owner('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: issues.map(issue => issue.id), changes: { statusId: project.statuses[1].id, labelIds: ['missing'] } })).status, 422);
  assert.equal((await board()).columns[0].issues.length, 3);
});
test('bulk cross-project issue and contradictory label edits are rejected', async () => {
  const other = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'OT', name: 'Other' })).data.project;
  const foreign = (await owner('POST', '/projects/' + other.id + '/issues', { title: 'Other issue' })).data.issue;
  assert.equal((await owner('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: [issues[0].id, foreign.id], changes: { statusId: project.statuses[1].id } })).status, 422);
  assert.equal((await owner('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: [issues[0].id], addLabelIds: [label.id], removeLabelIds: [label.id] })).status, 422);
  assert.equal((await board()).columns[0].issues.length, 3);
});
test('bulk label add and remove preserves unrelated labels and clears assignee', async () => {
  const path = '/projects/' + project.id + '/issues/bulk';
  await owner('POST', path, { issueIds: [issues[0].id], addLabelIds: [label.id] });
  assert.equal((await owner('GET', '/issues/' + issues[0].id)).data.issue.labels.length, 1);
  await owner('POST', path, { issueIds: [issues[0].id], changes: { assigneeId: null }, removeLabelIds: [label.id] });
  assert.deepEqual((await owner('GET', '/issues/' + issues[0].id)).data.issue.labels, []);
});
test('guest can view granted board but cannot move or bulk edit', async () => {
  assert.equal((await guest('GET', '/projects/' + project.id + '/board')).status, 403);
  await owner('POST', '/projects/' + project.id + '/guests', { userId: guestId });
  assert.equal((await guest('GET', '/projects/' + project.id + '/board')).status, 200);
  assert.equal((await guest('POST', '/issues/' + issues[0].id + '/move', { statusId: project.statuses[1].id })).status, 403);
  assert.equal((await guest('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: [issues[0].id], changes: { statusId: project.statuses[1].id } })).status, 403);
});
test('archive blocks moves and bulk and board mutations emit full issue state', async () => {
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  await owner('POST', '/issues/' + issues[0].id + '/move', { statusId: project.statuses[1].id });
  const event = events.find(event => event.action === 'moved');
  assert.equal(event.before.statusId, project.statuses[0].id); assert.equal(event.after.statusId, project.statuses[1].id);
  assert(event.actorId && event.time && Array.isArray(event.after.labels));
  await owner('PATCH', '/projects/' + project.id, { archived: true });
  assert.equal((await owner('POST', '/issues/' + issues[1].id + '/move', { statusId: project.statuses[1].id })).status, 409);
});
test('rank arithmetic handles boundary insertion and exhausted precision', () => {
  assert.equal(rankBetween(null, null), 1024); assert.equal(rankBetween(1024, 2048), 1536);
  assert.equal(rankBetween(1, 1), null); assert.equal(rankBetween(Number.MAX_VALUE, null), null);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toggleSelection, moveBody, bulkChanges, destinationAt } from '../src/pages/work/board-state.js';
test('board selection toggles independently without changing prior state', () => {
  const original = new Set(['a']); const next = toggleSelection(original, 'b');
  assert.deepEqual([...next], ['a', 'b']); assert.deepEqual([...original], ['a']); assert.deepEqual([...toggleSelection(next, 'a')], ['b']);
});
test('drag destination request removes self anchor and retains valid card anchor', () => {
  assert.deepEqual(moveBody({ statusId: 's', beforeId: 'a' }, 'a'), { statusId: 's' });
  assert.deepEqual(moveBody({ statusId: 's', beforeId: 'b' }, 'a'), { statusId: 's', beforeId: 'b' });
});
test('bulk form maps clear assignee and replacement labels deliberately', () => {
  assert.deepEqual(bulkChanges({ statusId: 'done', assigneeId: '__unassigned', labelsMode: 'replace', labelIds: [] }), { changes: { statusId: 'done', assigneeId: null, labelIds: [] } });
  assert.deepEqual(bulkChanges({ labelsMode: 'add', labelIds: ['label'] }), { changes: {}, addLabelIds: ['label'] });
});
test('pointer coordinates resolve column and card through actual DOM contract', () => {
  const doc = { elementFromPoint(x, y) { assert.equal(x, 20); assert.equal(y, 40); return { closest(selector) { return selector === '[data-status-id]' ? { dataset: { statusId: 'done' } } : { dataset: { issueId: 'anchor' } }; } }; } };
  assert.deepEqual(destinationAt(doc, 20, 40), { statusId: 'done', beforeId: 'anchor' });
  assert.equal(destinationAt({ elementFromPoint: () => null }, 0, 0), null);
});
